<script setup>
import { ref, watch, computed } from 'vue'
import { Plus, Trash2, Archive, RotateCcw } from 'lucide-vue-next'
import { api } from '../api'
import { useWorkboard } from '../stores/workboard'
import InfoTooltip from './InfoTooltip.vue'
const emit=defineEmits(['open-task'])
const store=useWorkboard(), tab=ref('board'), name=ref(''),description=ref(''),revision=ref(0),memberName=ref(''),memberRole=ref('editor'),labelTitle=ref(''),labelColor=ref('#3b82f6'),trash=ref({tasks:[],columns:[]}),activity=ref([]),columnForms=ref([])
const archivedTasks=ref([]),archiveNext=ref(null)
async function loadArchive(append=false) {const page=await api(append?archiveNext.value:`tasks/?board=${store.selected}&archived=true`);archivedTasks.value=append?[...archivedTasks.value,...page.results]:page.results;archiveNext.value=page.next?.replace(/^https?:\/\/[^/]+\/api\//,'') ?? null}
const editingLabel=ref(null),editLabelTitle=ref(''),editLabelColor=ref('#3b82f6')
function editLabel(label) {editingLabel.value=label.id;editLabelTitle.value=label.title;editLabelColor.value=label.color}
async function saveLabel() {await store.run(async()=>{await store.mutate(`labels/${editingLabel.value}/`,'PATCH',{title:editLabelTitle.value,color:editLabelColor.value});editingLabel.value=null;reset()})}
function reset() {name.value=store.board.title;description.value=store.board.description;revision.value=store.board.revision;columnForms.value=store.board.columns.map(c=>({...c,wip_limit:c.wip_limit ?? ''}))}
watch(()=>store.selected,reset,{immediate:true})
async function refreshLists() { if(!store.board)return; if(tab.value==='trash' && store.canWrite)trash.value=await api(`boards/${store.selected}/trash_items/`);if(tab.value==='archive')await loadArchive();if(tab.value==='activity')activity.value=await api(`boards/${store.selected}/activity/`) }
watch([tab,()=>store.board?.revision],()=>store.run(refreshLists))
async function saveBoard() {await store.run(async()=>{await store.mutate(`boards/${store.selected}/`,'PATCH',{title:name.value,description:description.value},revision.value);reset()})}
async function archiveBoard() { const id=store.selected,previous=store.board.archived;await store.run(async()=>{await store.mutate(`boards/${id}/`,'PATCH',{archived:!previous});store.offerUndo(previous?'Quadro desarquivado.':'Quadro arquivado.',()=>store.mutate(`boards/${id}/`,'PATCH',{archived:previous}));reset()}) }
async function deleteBoard() { if(!window.confirm('Enviar este quadro e seu conteúdo para a lixeira? Você poderá restaurá-lo.'))return;const id=store.selected;await store.run(async()=>{await store.mutate(`boards/${id}/`,'DELETE');store.offerUndo('Quadro enviado para a lixeira.',()=>store.restoreBoard(id))}) }
async function saveColumn(col) {await store.run(async()=>{await store.mutate(`columns/${col.id}/`,'PATCH',{title:col.title,kind:col.kind,wip_limit:col.wip_limit===''?null:Number(col.wip_limit),position:Number(col.position)},revision.value);reset()})}
async function deleteColumn(col) {if(!window.confirm('Excluir a coluna? Ela precisa estar vazia e poderá ser restaurada.'))return;await store.run(async()=>{await store.mutate(`columns/${col.id}/`,'DELETE',undefined,revision.value);store.offerUndo('Coluna enviada para a lixeira.',()=>store.mutate(`columns/${col.id}/restore/`,'POST',{}));reset()})}
async function addMember() {await store.run(async()=>{await store.mutate('members/','POST',{board:store.selected,username:memberName.value,role:memberRole.value});memberName.value='';reset()})}
async function changeRole(member,event) {await store.run(async()=>{await store.mutate(`members/${member.id}/`,'PATCH',{role:event.target.value});reset()})}
async function removeMember(member) {const board=store.selected;if(!window.confirm(`Remover ${member.user_name} do quadro?`))return;await store.run(async()=>{await store.mutate(`members/${member.id}/`,'DELETE');store.offerUndo('Membro removido.',()=>store.mutate('members/','POST',{board,username:member.user_name,role:member.role}));reset()})}
async function addLabel() {await store.run(async()=>{await store.mutate('labels/','POST',{board:store.selected,title:labelTitle.value,color:labelColor.value});labelTitle.value='';reset()})}
async function deleteLabel(label) {if(!window.confirm('Excluir esta etiqueta de todos os cartões?'))return;const board=store.selected,taskIds=store.board.columns.flatMap(c=>c.tasks).filter(t=>t.labels.includes(label.id)).map(t=>t.id);await store.run(async()=>{await store.mutate(`labels/${label.id}/`,'DELETE');store.offerUndo('Etiqueta removida.',async()=>{const restored=await store.mutate('labels/','POST',{board,title:label.title,color:label.color});for(const id of taskIds){const task=store.board.columns.flatMap(c=>c.tasks).find(t=>t.id===id);if(task)await store.mutate(`tasks/${id}/`,'PATCH',{labels:[...task.labels,restored.id]})}});reset()})}
async function restore(kind,id) {await store.run(async()=>{await store.mutate(`${kind}/${id}/restore/`,'POST',{});await refreshLists();reset()})}
</script>
<template>
  <section class="settings-workspace"><div class="section-heading"><div><span class="eyebrow">SEU QUADRO, SUAS REGRAS</span><h2>Configurações e equipe</h2><p>Organize o fluxo, compartilhe o trabalho e mantenha tudo rastreável.</p></div></div><div class="detail-tabs settings-tabs"><button :class="{active:tab==='board'}" @click="tab='board'">Quadro e colunas</button><button :class="{active:tab==='team'}" @click="tab='team'">Equipe</button><button :class="{active:tab==='labels'}" @click="tab='labels'">Etiquetas</button><button :class="{active:tab==='archive'}" @click="tab='archive'">Arquivados</button><button v-if="store.canWrite" :class="{active:tab==='trash'}" @click="tab='trash'">Lixeira</button><button :class="{active:tab==='activity'}" @click="tab='activity'">Atividades</button></div>
    <div v-if="tab==='board'" class="settings-grid"><section class="settings-card"><h3>Dados do quadro</h3><form @submit.prevent="saveBoard"><label>Nome do quadro<input v-model="name" required maxlength="120" :disabled="!store.canManage"></label><label>Descrição do quadro<textarea v-model="description" maxlength="2000" rows="3" :disabled="!store.canManage"></textarea></label><button v-if="store.canManage" class="primary" :disabled="store.busy">Salvar quadro</button></form><div v-if="store.canManage" class="settings-actions"><button class="secondary" :disabled="store.busy" @click="archiveBoard"><Archive :size="16"/>{{store.board.archived?'Desarquivar quadro':'Arquivar quadro'}}</button><button v-if="store.board.role==='owner'" class="danger" :disabled="store.busy" @click="deleteBoard"><Trash2 :size="16"/> Excluir quadro</button></div><p v-if="store.error" class="error">{{store.error}}<button class="text-button" @click="reset">Recarregar formulário</button></p></section><section class="settings-card"><h3>Colunas e limites WIP</h3><p>Defina o tipo de cada etapa. Colunas do tipo “Concluída” alimentam os indicadores. Para mudar o tipo ou excluir, a coluna deve estar vazia.</p><form v-for="col in columnForms" :key="col.id" class="column-form" @submit.prevent="saveColumn(col)"><label>Nome da coluna<input v-model="col.title" required maxlength="80" :disabled="!store.canManage || !store.canWrite"></label><div class="form-row"><label>Tipo<select v-model="col.kind" :disabled="!store.canManage || !store.canWrite"><option value="backlog">A fazer</option><option value="progress">Em execução</option><option value="done">Concluída</option></select></label><div class="label-field"><div class="label-caption"><label :for="`wip-${col.id}`">Limite WIP</label><InfoTooltip label="O que significa WIP?" text="WIP significa Work in Progress (trabalho em andamento). É o limite de tarefas simultâneas na coluna. Exemplo: com limite 3, uma quarta tarefa só entra quando uma das três sair. Deixe vazio para não limitar."/></div><input :id="`wip-${col.id}`" v-model="col.wip_limit" type="number" min="1" placeholder="Sem limite" :disabled="!store.canManage || !store.canWrite"></div></div><label>Ordem da coluna<input v-model="col.position" type="number" min="0" :disabled="!store.canManage || !store.canWrite"></label><div v-if="store.canManage && store.canWrite" class="modal-actions"><button type="button" class="danger" :disabled="store.busy" :aria-label="`Excluir coluna ${col.title}`" @click="deleteColumn(col)"><Trash2 :size="14"/> Excluir</button><button class="secondary" :disabled="store.busy">Salvar coluna</button></div></form></section></div>
    <section v-else-if="tab==='team'" class="settings-card"><h3>Membros do quadro</h3><p>Adicione um usuário já cadastrado no WorkBoard. Leitores consultam; editores trabalham nos cartões; administradores gerenciam o quadro. Apenas o dono pode nomear ou remover administradores.</p><form v-if="store.canManage && store.canWrite" class="member-form" @submit.prevent="addMember"><label>Usuário do membro<input v-model="memberName" required maxlength="150" placeholder="Nome de usuário"></label><label>Perfil<select v-model="memberRole"><option value="viewer">Leitor</option><option value="editor">Editor</option><option v-if="store.board.role==='owner'" value="admin">Administrador</option></select></label><button class="primary" :disabled="store.busy"><Plus :size="16"/> Adicionar membro</button></form><div v-for="member in store.board.members" :key="member.user" class="member-row"><div class="avatar">{{member.user_name[0].toUpperCase()}}</div><strong>{{member.user_name}}</strong><span v-if="member.role==='owner'" class="sprint-status">Dono</span><select v-else :value="member.role" :disabled="!store.canManage || !store.canWrite || store.busy || (member.role==='admin' && store.board.role!=='owner')" :aria-label="`Perfil de ${member.user_name}`" @change="changeRole(member,$event)"><option value="viewer">Leitor</option><option value="editor">Editor</option><option v-if="store.board.role==='owner' || member.role==='admin'" value="admin">Administrador</option></select><button v-if="member.id && store.canManage && store.canWrite" :disabled="store.busy" :aria-label="`Remover ${member.user_name}`" @click="removeMember(member)"><Trash2 :size="16"/></button></div></section>
    <section v-else-if="tab==='labels'" class="settings-card"><h3>Etiquetas do projeto</h3><form v-if="store.canManage && store.canWrite" class="member-form" @submit.prevent="addLabel"><label>Nome da etiqueta<input v-model="labelTitle" required maxlength="40" placeholder="Backend, design, correção…"></label><label>Cor<input v-model="labelColor" type="color"></label><button class="primary" :disabled="store.busy"><Plus :size="16"/> Criar etiqueta</button></form><form v-if="editingLabel" class="member-form" @submit.prevent="saveLabel"><label>Editar nome da etiqueta<input v-model="editLabelTitle" required maxlength="40"></label><label>Editar cor<input v-model="editLabelColor" type="color"></label><button class="primary" :disabled="store.busy">Salvar etiqueta</button><button type="button" @click="editingLabel=null">Cancelar</button></form><div class="label-list"><div v-for="label in store.board.labels" :key="label.id"><span class="label-chip" :style="{'--label-color':label.color}">{{label.title}}</span><button v-if="store.canManage && store.canWrite" :disabled="store.busy" :aria-label="`Editar etiqueta ${label.title}`" @click="editLabel(label)">Editar</button><button v-if="store.canManage && store.canWrite" :disabled="store.busy" :aria-label="`Excluir etiqueta ${label.title}`" @click="deleteLabel(label)"><Trash2 :size="14"/></button></div></div></section>
    <section v-else-if="tab==='archive'" class="settings-card"><h3>Tarefas arquivadas</h3><p>Arquivar retira o cartão do fluxo e das métricas atuais, preservando seu conteúdo.</p><div v-for="task in archivedTasks" :key="task.id" class="trash-row"><strong>{{task.title}}</strong><button class="secondary" @click="emit('open-task',task)">Abrir tarefa</button></div><button v-if="archiveNext" class="text-button" @click="store.run(()=>loadArchive(true))">Carregar mais arquivados</button><p v-if="!archivedTasks.length">Nenhuma tarefa arquivada.</p></section>
    <section v-else-if="tab==='trash'" class="settings-card"><h3>Itens excluídos</h3><p>Restaure primeiro a coluna, se ela também foi excluída. A restauração de tarefas respeita o limite WIP.</p><div v-for="col in trash.columns" :key="`c${col.id}`" class="trash-row"><span>Coluna · {{col.title}}</span><button :disabled="store.busy || !store.canManage" @click="restore('columns',col.id)"><RotateCcw :size="15"/> Restaurar coluna</button></div><div v-for="task in trash.tasks" :key="task.id" class="trash-row"><span>Tarefa · {{task.title}}</span><button :disabled="store.busy" @click="restore('tasks',task.id)"><RotateCcw :size="15"/> Restaurar tarefa</button></div><p v-if="!trash.tasks.length && !trash.columns.length">A lixeira está vazia.</p></section>
    <section v-else class="settings-card activity-list"><h3>Histórico do quadro</h3><article v-for="item in activity" :key="item.id"><strong>{{item.actor_name}}</strong><p>{{item.message}}</p><small>{{new Date(item.created_at).toLocaleString('pt-BR')}}</small></article><p v-if="!activity.length">Nenhuma atividade registrada.</p></section>
  </section>
</template>
